import type { ReactNode } from "react";
import type { VariantProps } from "class-variance-authority";
import { Tag, tagVariants, type TagProps } from "../../tag";

type StatusBadgeVariantProps = Omit<
  VariantProps<typeof tagVariants>,
  "variant" | "weight" | "size" | "surface"
> & { tone?: TagProps["variant"] };

/** Compatibility adapter for canvas callers; Tag owns all badge styling. */
export function statusBadgeVariants({
  tone = "warning",
  ...props
}: StatusBadgeVariantProps = {}) {
  return tagVariants({ ...props, variant: tone, size: "sm" });
}

export interface StatusBadgeProps extends Omit<
  VariantProps<typeof statusBadgeVariants>,
  "hasLeadingIcon" | "hasTrailingIcon"
> {
  /** Rendered before the label, e.g. a check for `TESTED` or a flask for `UNTESTED`. */
  icon?: ReactNode;
  /** Optional trailing decoration; status icons conventionally use the leading `icon` prop. */
  trailingIcon?: ReactNode;
  children: ReactNode;
  className?: string;
}

/** Canvas vocabulary adapter for the shared Tag. */
export function StatusBadge({
  tone = "warning",
  icon,
  trailingIcon,
  children,
  className,
}: StatusBadgeProps) {
  return (
    <Tag
      variant={tone}
      size="sm"
      leadingIcon={icon}
      trailingIcon={trailingIcon}
      className={className}
    >
      {children}
    </Tag>
  );
}

import { useEffect, useRef } from "react";
import { motion, useAnimation } from "framer-motion";
import { useSystemReducedMotion } from "../../use-reduced-motion";
import { DocumentNode } from "./DocumentNode";
import { FutureStepNode } from "./FutureStepNode";
import { NewItemCTANode } from "./NewItemCTANode";
import { NodeFrame } from "./NodeFrame";
import { ProblemStatementNode } from "./ProblemStatementNode";
import { PrototypeNode } from "./PrototypeNode";
import type {
  DocumentNodeData,
  FutureStepData,
  NewItemCTAData,
  ProblemStatementData,
  PrototypeNodeData,
} from "../types";

// Keys here must match `FlowchartNodeSpec['kind']` values in types.ts. The type
// annotation pins each renderer's `data` prop to its matching shape in types.ts.
export const nodeTypes: {
  content: (props: {
    data: { content: React.ReactNode };
  }) => React.ReactElement;
  problem: (props: { data: ProblemStatementData }) => React.ReactElement;
  futureStep: (props: { data: FutureStepData }) => React.ReactElement;
  document: (props: { data: DocumentNodeData }) => React.ReactElement;
  newItemCta: (props: { data: NewItemCTAData }) => React.ReactElement;
  prototype: (props: { data: PrototypeNodeData }) => React.ReactElement;
} = {
  content: ({ data }) => <>{data.content}</>,
  problem: ProblemStatementNode,
  futureStep: FutureStepNode,
  document: DocumentNode,
  prototype: PrototypeNode,
  // NewItemCTANode takes flat `icon`/`label`/`onClick` props (it's also usable
  // standalone outside the node registry, with no title) — the frame + title
  // are added here, at the flowchart-node adaptation layer.
  newItemCta: NewItemCTAFlowNode,
};

function NewItemCTAFlowNode({
  data,
  disableMotion = false,
}: {
  data: NewItemCTAData;
  disableMotion?: boolean;
}) {
  const controls = useAnimation();
  const reduceMotion = useSystemReducedMotion();
  const previousPulseToken = useRef(data.pulseToken);

  useEffect(() => {
    if (previousPulseToken.current === data.pulseToken) return;
    previousPulseToken.current = data.pulseToken;
    if (disableMotion || reduceMotion || data.pulseToken === undefined) return;
    void controls.start({
      scale: [1, 1.06, 1],
      transition: { duration: 0.5, ease: "easeInOut" },
    });
  }, [data.pulseToken, disableMotion, reduceMotion, controls]);

  return (
    <motion.div
      initial={false}
      animate={controls}
      style={{ willChange: "transform" }}
    >
      <NodeFrame title={data.title}>
        <div className="p-2">
          <NewItemCTANode
            icon={data.icon}
            label={data.label}
            onClick={data.onClick}
            disableMotion={disableMotion}
          />
        </div>
      </NodeFrame>
    </motion.div>
  );
}

import type { ReactNode } from "react";
import type { Viewport } from "./viewport";

/**
 * Generic id for a column. Consumers define their own set of column ids
 * (e.g. 'problem' | 'prototype' | 'approval') and pass a matching `columns`
 * config into <FlowchartCanvas />.
 */
export type ColumnId = string;

export interface ColumnConfig {
  /** Stable identifier, referenced by nodes via `node.column`. */
  id: ColumnId;
  /** Fixed pixel width used for layout and for the node's rendered width. */
  width: number;
  /** Vertical alignment of this column's node stack relative to the tallest column. */
  align?: "start" | "center";
  /** Align cards to the top or center of their shared row slot. */
  rowAlign?: "start" | "center";
}

/** A single "As a / I must / but / This happens / This costs / It happens" line. */
export interface ProblemStatementLine {
  /** Muted lead-in text, e.g. "As a". Omit for lines with no lead-in. */
  lead?: string;
  /** Emphasized (dark) text that follows the lead-in. */
  body: string;
}

/** Frosted-glass CTA shown over a node's content area on hover. */
export interface NodeHoverCta {
  /** Retained for compatibility; cards use the shared Open icon. */
  icon: ReactNode;
  /** Accessible action name; the visible label is always Open. */
  label: string;
  onClick: () => void;
}

export interface ProblemStatementData extends Record<string, unknown> {
  title: string;
  status: "incomplete" | "complete";
  lines: ProblemStatementLine[];
  hoverCta?: NodeHoverCta;
}

/** A pipeline stage that isn't available yet — locked until an upstream prerequisite is met. */
export interface FutureStepData extends Record<string, unknown> {
  title: string;
  locked: boolean;
  /** Text shown under the lock icon, or as the unlocked body if `locked` is false. */
  caption: string;
}

/** A document preview card (e.g. a generated prototype plan) with a validation-status badge. */
export interface DocumentNodeData extends Record<string, unknown> {
  title: string;
  status: "draft" | "scoping" | "building" | "refining" | "validated";
  documentTitle: string;
  /** Full body text; clipped to a fixed preview height with a linear fade. */
  documentBody: string;
  hoverCta?: NodeHoverCta;
}

/** The three states a canvas card's body can be in. */
export type CardContentState = "locked" | "cta" | "filled";

/** Status pills a prototype card can carry. Rendered in the order given, max two. */
export type PrototypeBadgeKind =
  | "AWAITING APPROVAL"
  | "BUILDING"
  | "BUILT"
  | "UNTESTED"
  | "TESTED"
  | "INCOMPLETE"
  | "COMPLETE";

/**
 * A prototype card. Unlike {@link DocumentNodeData} it carries a pair of
 * independent status pills (build state and test state) and its body can be
 * locked or a call to action, not only a document preview.
 */
export interface PrototypeNodeData extends Record<string, unknown> {
  /** Frame title, e.g. "Prototype A". */
  title: string;
  badges: PrototypeBadgeKind[];
  contentState: CardContentState;
  /** `filled` — document preview. */
  documentTitle?: string;
  documentBody?: string;
  /** `locked` and `cta` — the single line of copy. */
  label?: string;
  /** `cta` — invoked when the card is clicked. */
  onClick?: () => void;
  /** `filled` — enables the shared Open affordance. */
  onEdit?: () => void;
}

/** A clickable card that prompts creating a new item (e.g. "Create a new prototype"). */
export interface NewItemCTAData extends Record<string, unknown> {
  /** Frame title shown above the CTA, e.g. "Prototype C". */
  title: string;
  icon: ReactNode;
  label: string;
  onClick?: () => void;
  /** Change this token to pulse the node. Its initial value never animates. */
  pulseToken?: number;
}

interface FlowNodeBase {
  /** Indent the card without shrinking it; layout reserves the extra column space. */
  inset?: number;
  id: string;
  column: ColumnId;
  /**
   * Nodes across different columns that share a `row` value are vertically
   * centered as one unit — e.g. a Solution node and its Report/Approval
   * nodes, so the shorter side pads to match the taller one instead of the
   * two columns drifting apart. Omit for independent stacking (the default).
   */
  row?: string;
}

export type ProblemStatementNodeSpec = FlowNodeBase & {
  kind: "problem";
  data: ProblemStatementData;
};

export type FutureStepNodeSpec = FlowNodeBase & {
  kind: "futureStep";
  data: FutureStepData;
};

export type DocumentNodeSpec = FlowNodeBase & {
  kind: "document";
  data: DocumentNodeData;
};

export type NewItemCTANodeSpec = FlowNodeBase & {
  kind: "newItemCta";
  data: NewItemCTAData;
};

export type PrototypeNodeSpec = FlowNodeBase & {
  kind: "prototype";
  data: PrototypeNodeData;
};

/** Host-supplied content participates in canvas sizing, panning and connectors. */
export type ContentNodeSpec = FlowNodeBase & {
  kind: "content";
  data: { content: ReactNode };
};

/** Union of every node spec the canvas knows how to render. Extend this when adding node kinds. */
export type FlowchartNodeSpec =
  | ProblemStatementNodeSpec
  | FutureStepNodeSpec
  | DocumentNodeSpec
  | NewItemCTANodeSpec
  | PrototypeNodeSpec
  | ContentNodeSpec;

export interface FlowchartEdgeSpec {
  /** Connect the parent bottom to indented children with a rounded branch. */
  routing?: "bottom-left";
  id: string;
  source: string;
  target: string;
  /**
   * `"dotted"` marks a connection to something not yet reachable — the board
   * uses it for the edge into a locked report. Defaults to `"solid"`.
   */
  variant?: "solid" | "dotted";
}

export interface FlowchartCanvasHandle {
  /**
   * Pans — and, if `scale` is given, also zooms — so the column is centered
   * in the viewport. `scale` defaults to the current scale (a pure pan) and
   * is clamped to `[fitScale, maxScale]`.
   */
  focusColumn: (
    columnId: ColumnId,
    options?: { duration?: number; scale?: number },
  ) => void;
  /** Re-fits the whole board and re-arms automatic re-fit on resize. */
  fitToContent: (options?: { duration?: number }) => void;
  /** Zooms about the viewport center. Clamped to `[fitScale, maxScale]`. */
  zoomTo: (scale: number, options?: { duration?: number }) => void;
  /** The current pan/zoom camera. */
  getViewport: () => Viewport;
}

import type { PositionedNode } from "./layout";

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * The pan/zoom camera. `screen = translate + scale · world` — see the
 * transform on the content layer in `FlowchartCanvas`, which applies
 * `translate3d(x, y, 0) scale(scale)` with `transformOrigin: "0 0"`.
 */
export interface Viewport {
  x: number;
  y: number;
  scale: number;
}

export interface Size {
  width: number;
  height: number;
}

export interface ContentBounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  width: number;
  height: number;
}

// ─── Constants ────────────────────────────────────────────────────────────────

/** Default upper zoom bound (100%). */
export const MAX_SCALE = 1;
/** Absolute floor so a pathological (near-empty) board can't compute a runaway scale. */
export const MIN_SCALE_FLOOR = 0.05;
/** Default breathing room, in px, between the fitted board and the viewport edge. */
export const DEFAULT_FIT_PADDING = 48;
/** Wheel-to-zoom multiplier: factor = exp(-clampedDeltaPx * ZOOM_SENSITIVITY). */
export const ZOOM_SENSITIVITY = 0.01;
/** Caps a single wheel event's delta so one mouse notch can't teleport the scale. */
export const MAX_WHEEL_DELTA_PX = 50;
/** Below this, two viewports are treated as identical (avoids float-jitter re-renders). */
export const VIEWPORT_EPSILON = 0.01;

const LINE_HEIGHT_PX = 16;

export const EMPTY_BOUNDS: ContentBounds = {
  minX: 0,
  minY: 0,
  maxX: 0,
  maxY: 0,
  width: 0,
  height: 0,
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

export const clamp = (value: number, lo: number, hi: number): number =>
  Math.min(hi, Math.max(lo, value));

/**
 * Real bounding box of the laid-out nodes. Does NOT assume the top-left is
 * `(0, 0)` — `computeLayout` leaves an empty column with no nodes, so the
 * first column can be empty and `minX` can be positive.
 */
export function computeContentBounds(
  positioned: PositionedNode[],
): ContentBounds {
  if (positioned.length === 0) return EMPTY_BOUNDS;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const p of positioned) {
    minX = Math.min(minX, p.x);
    minY = Math.min(minY, p.y);
    maxX = Math.max(maxX, p.x + p.width);
    maxY = Math.max(maxY, p.y + p.height);
  }
  return { minX, minY, maxX, maxY, width: maxX - minX, height: maxY - minY };
}

/** Keeps the leading content edge visible when panning toward either viewport edge. */
export function constrainViewportToContent(
  viewport: Viewport,
  bounds: ContentBounds,
  container: Size,
  padding = DEFAULT_FIT_PADDING,
): Viewport {
  if (
    bounds.width <= 0 ||
    bounds.height <= 0 ||
    container.width <= 0 ||
    container.height <= 0
  )
    return viewport;
  const insetX = Math.min(padding, container.width / 2);
  const insetY = Math.min(padding, container.height / 2);
  const x = clamp(
    viewport.x,
    insetX - bounds.maxX * viewport.scale,
    container.width - insetX - bounds.minX * viewport.scale,
  );
  const y = clamp(
    viewport.y,
    insetY - bounds.maxY * viewport.scale,
    container.height - insetY - bounds.minY * viewport.scale,
  );
  return x === viewport.x && y === viewport.y
    ? viewport
    : { ...viewport, x, y };
}

/** The scale that fits `bounds` entirely inside `container`, minus `padding` on every side. */
export function computeFitScale(
  bounds: ContentBounds,
  container: Size,
  padding: number,
  maxScale: number,
): number {
  if (bounds.width <= 0 || bounds.height <= 0) return maxScale;
  if (container.width <= 0 || container.height <= 0) return maxScale;
  const availW = Math.max(1, container.width - padding * 2);
  const availH = Math.max(1, container.height - padding * 2);
  const raw = Math.min(availW / bounds.width, availH / bounds.height);
  return clamp(raw, MIN_SCALE_FLOOR, maxScale);
}

/** The viewport that centers `bounds` in `container` at the given `scale`. */
export function computeFitViewport(
  bounds: ContentBounds,
  container: Size,
  scale: number,
): Viewport {
  return {
    scale,
    x: (container.width - bounds.width * scale) / 2 - bounds.minX * scale,
    y: (container.height - bounds.height * scale) / 2 - bounds.minY * scale,
  };
}

/**
 * Resolves the one-shot `initialView="column"` starting viewport — centered
 * on `target`'s column at `scale`, computed only once real content exists.
 *
 * Returns `null` while there isn't yet enough information to center
 * correctly: `target`'s column has no positioned nodes at all (the data
 * this board renders is still loading), or any of its nodes are still sized
 * off `ESTIMATED_NODE_HEIGHT` (not yet reported by a `ResizeObserver`).
 * Callers that lock in the first non-null result forever (as
 * `FlowchartCanvas` does) must not lock in on a `null` — the board would be
 * stuck off-center once the real data/heights land, since this only ever
 * runs once.
 *
 * A `target` of `undefined` (no columns configured at all) resolves
 * immediately to the plain origin — there's no column content to wait for.
 */
export function resolveInitialColumnViewport(
  target: string | undefined,
  positioned: PositionedNode[],
  measuredHeights: Record<string, number>,
  container: Size,
  scale: number,
): Viewport | null {
  if (!target) return { x: 0, y: 0, scale };

  const targetNodes = positioned.filter((p) => p.spec.column === target);
  if (targetNodes.length === 0) return null;
  const heightsMeasured = targetNodes.every(
    (p) => measuredHeights[p.spec.id] !== undefined,
  );
  if (!heightsMeasured) return null;

  const bounds = computeContentBounds(targetNodes);
  const centerX = (bounds.minX + bounds.maxX) / 2;
  const centerY = (bounds.minY + bounds.maxY) / 2;
  return {
    scale,
    x: container.width / 2 - scale * centerX,
    y: container.height / 2 - scale * centerY,
  };
}

export function isSameViewport(a: Viewport, b: Viewport): boolean {
  return (
    Math.abs(a.x - b.x) < VIEWPORT_EPSILON &&
    Math.abs(a.y - b.y) < VIEWPORT_EPSILON &&
    Math.abs(a.scale - b.scale) < VIEWPORT_EPSILON
  );
}

/**
 * Zooms `v` to `requestedScale` (clamped to `[minScale, maxScale]`) while
 * keeping the world point under screen point `(px, py)` fixed. Returns `v`
 * itself (same reference) when the clamped scale doesn't change, so calling
 * this at the clamp boundary — e.g. holding a pinch at the floor — never
 * produces a new object and never triggers a re-render.
 */
export function zoomAbout(
  v: Viewport,
  requestedScale: number,
  px: number,
  py: number,
  minScale: number,
  maxScale: number,
): Viewport {
  const scale = clamp(requestedScale, minScale, maxScale);
  if (scale === v.scale) return v;
  const k = scale / v.scale;
  return {
    scale,
    x: px - k * (px - v.x),
    y: py - k * (py - v.y),
  };
}

/**
 * Normalizes a wheel event's vertical delta into a zoom factor. Trackpad
 * pinch on macOS arrives as `wheel` with `ctrlKey: true` and a small
 * `deltaY`; a physical mouse wheel with ctrl held delivers a much larger
 * one. Exponential response makes zooming in and back out exact inverses
 * and keeps the result always positive.
 */
export function wheelZoomFactor(
  e: Pick<WheelEvent, "deltaY" | "deltaMode">,
  viewportHeight: number,
): number {
  const px =
    e.deltaMode === 1
      ? e.deltaY * LINE_HEIGHT_PX
      : e.deltaMode === 2
        ? e.deltaY * viewportHeight
        : e.deltaY;
  const clamped = clamp(px, -MAX_WHEEL_DELTA_PX, MAX_WHEEL_DELTA_PX);
  return Math.exp(-clamped * ZOOM_SENSITIVITY);
}
